def IsPopOrder(pushV, popV):
    if len(pushV) != len(popV):
        return False
    stack, j = [], 0
    for v in pushV:
        stack.append(v)                       # 1. 按顺序压入
        while stack and stack[-1] == popV[j]:  # 2. 能弹就弹
            stack.pop()
            j += 1
    return j == len(popV)                     # 3. 全部匹配才算合法
